import React, { useState } from 'react';
import { machineApi } from '../api/client';
import Toast from './Toast';
import {
  X,
  Cpu,
  Activity,
  ShieldCheck,
  AlertTriangle,
  Wrench,
  Clock,
  Sparkles,
  Zap,
  Gauge,
  Thermometer,
  FileText,
  CheckCircle2,
  PlusCircle,
  Save,
} from 'lucide-react';

const MachineDetailsModal = ({ machine: initialMachine, onClose }) => {
  const [machine, setMachine] = useState(initialMachine);
  const [activeTab, setActiveTab] = useState('overview');
  const [showProblemForm, setShowProblemForm] = useState(false);

  // Problem Form State
  const [problemName, setProblemName] = useState('');
  const [severity, setSeverity] = useState('High');
  const [rootCause, setRootCause] = useState('');
  const [sensorTriggered, setSensorTriggered] = useState('Motor Temp Sensor TS-01');
  const [submitting, setSubmitting] = useState(false);
  const [toast, setToast] = useState(null);

  if (!machine) return null;

  const handleRecordProblemSubmit = async (e) => {
    e.preventDefault();
    if (!problemName || !rootCause) {
      setToast({ message: 'Please enter both Problem Name and Reason for Problem', type: 'error' });
      return;
    }

    try {
      setSubmitting(true);
      const machineId = machine._id || machine.machineId;
      const res = await machineApi.recordProblem(machineId, {
        name: problemName,
        severity,
        rootCause,
        sensorTriggered,
        user: 'Anita Desai',
      });

      if (res.data.success) {
        setMachine(res.data.data);
        setToast({ message: 'Problem reason recorded successfully!', type: 'success' });
        setShowProblemForm(false);
        setProblemName('');
        setRootCause('');
      }
    } catch (err) {
      setToast({ message: 'Failed to record problem reason.', type: 'error' });
    } finally {
      setSubmitting(false);
    }
  };

  const getStatusBadge = (status) => {
    switch (status) {
      case 'Running':
        return <span className="badge badge-running"><span className="dot"></span> Running</span>;
      case 'Idle':
        return <span className="badge badge-idle"><span className="dot"></span> Idle</span>;
      case 'Maintenance':
        return <span className="badge badge-maintenance"><span className="dot"></span> Maintenance</span>;
      default:
        return <span className="badge">{status}</span>;
    }
  };

  const telemetry = machine.telemetry || {
    rpm: 980,
    temperature: '56.4',
    humidity: '65.2',
    vibration: '1.82',
    energyUsage: '14.2',
    runningHours: 4210,
  };

  const health = machine.machineHealth || {
    healthScore: machine.healthScore || 96,
    remainingUsefulLifeDays: 165,
    aiPrediction: 'Healthy - Optimal Operation',
    failureProbabilityPct: 4,
  };

  const maint = machine.maintenanceDetails || {
    maintenanceType: 'Preventive Servicing',
    issueDescription: 'Optimal operation; routine lube check scheduled',
    rootCause: 'None',
    engineer: machine.maintenanceEngineer || 'Anita Desai',
    startedOn: 'N/A',
    estimatedCompletion: 'N/A',
    priority: 'Normal',
    sparePartsRequired: ['Lube Oil ISO VG 220'],
    history: [],
  };

  const problems = machine.currentProblems || [];
  const timeline = machine.eventTimeline || [];
  const aiRecs = machine.aiRecommendations || {
    immediateAction: 'Inspect warp tension sensor optical lens',
    preventiveAction: 'Schedule spindle lube at next 500-hr mark',
    estimatedRisk: 'Low (3%)',
    recommendedInspectionDate: '2026-08-15',
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div
        className="modal-content modal-lg"
        onClick={(e) => e.stopPropagation()}
        style={{ background: 'var(--bg-card)', padding: '2rem', borderRadius: 'var(--radius-lg)' }}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'flex-start',
            borderBottom: '1px solid var(--border-subtle)',
            paddingBottom: '1.25rem',
            marginBottom: '1.25rem',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <div
              style={{
                width: '48px',
                height: '48px',
                borderRadius: 'var(--radius-md)',
                background: 'var(--status-critical-bg)',
                color: 'var(--accent-primary)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <Cpu size={26} />
            </div>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                <h2 style={{ fontSize: '1.4rem', fontWeight: '800', color: 'var(--text-primary)' }}>
                  {machine.assetName}
                </h2>
                {getStatusBadge(machine.currentStatus)}
              </div>
              <p style={{ fontSize: '0.88rem', color: 'var(--text-secondary)', fontWeight: '600', marginTop: '2px' }}>
                Machine ID: <strong style={{ color: 'var(--accent-primary)', fontFamily: 'JetBrains Mono' }}>{machine.machineId}</strong> • {machine.factoryName || 'TexTwin Primary Mill'} • {machine.productionLine || 'Line 1'}
              </p>
            </div>
          </div>
          <button className="drawer-close-btn" onClick={onClose}>
            <X size={20} />
          </button>
        </div>

        {/* 7-Section Navigation Tabs */}
        <div className="tab-nav">
          <button className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => setActiveTab('overview')}>
            <FileText size={15} style={{ display: 'inline', marginRight: '4px' }} /> 1. Overview
          </button>
          <button className={`tab-btn ${activeTab === 'telemetry' ? 'active' : ''}`} onClick={() => setActiveTab('telemetry')}>
            <Activity size={15} style={{ display: 'inline', marginRight: '4px' }} /> 2. Live Telemetry
          </button>
          <button className={`tab-btn ${activeTab === 'health' ? 'active' : ''}`} onClick={() => setActiveTab('health')}>
            <ShieldCheck size={15} style={{ display: 'inline', marginRight: '4px' }} /> 3. Health & RUL
          </button>
          <button className={`tab-btn ${activeTab === 'problems' ? 'active' : ''}`} onClick={() => setActiveTab('problems')}>
            <AlertTriangle size={15} style={{ display: 'inline', marginRight: '4px' }} /> 4. Problems ({problems.length})
          </button>
          <button className={`tab-btn ${activeTab === 'maintenance' ? 'active' : ''}`} onClick={() => setActiveTab('maintenance')}>
            <Wrench size={15} style={{ display: 'inline', marginRight: '4px' }} /> 5. Maintenance
          </button>
          <button className={`tab-btn ${activeTab === 'timeline' ? 'active' : ''}`} onClick={() => setActiveTab('timeline')}>
            <Clock size={15} style={{ display: 'inline', marginRight: '4px' }} /> 6. Timeline
          </button>
          <button className={`tab-btn ${activeTab === 'ai' ? 'active' : ''}`} onClick={() => setActiveTab('ai')}>
            <Sparkles size={15} style={{ display: 'inline', marginRight: '4px' }} /> 7. AI Advice
          </button>
        </div>

        {/* Tab 1: Machine Overview */}
        {activeTab === 'overview' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: '1.25rem' }}>
            <div style={{ padding: '1rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>MANUFACTURER & MODEL</div>
              <div style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '4px' }}>{machine.manufacturer} ({machine.modelNumber || 'N/A'})</div>
              <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', marginTop: '4px', fontWeight: '600' }}>Serial: {machine.serialNumber || 'SN-99102-X'}</div>
            </div>

            <div style={{ padding: '1rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>LOCATION & BAY</div>
              <div style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '4px' }}>{machine.physicalLocation || 'Floor 1 - Bay A'}</div>
              <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', marginTop: '4px', fontWeight: '600' }}>Dept: {machine.department || 'High-Speed Weaving'}</div>
            </div>

            <div style={{ padding: '1rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>ASSIGNED PERSONNEL</div>
              <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '4px' }}>Operator: {machine.assignedOperator || 'Rajesh Kumar'}</div>
              <div style={{ fontSize: '0.85rem', fontWeight: '700', color: 'var(--accent-primary)', marginTop: '2px' }}>Engineer: {machine.maintenanceEngineer || 'Anita Desai'}</div>
            </div>

            <div style={{ padding: '1rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>INSTALLATION & WARRANTY</div>
              <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '4px' }}>Installed: {machine.installationDate || '2023-01-15'}</div>
              <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', marginTop: '2px', fontWeight: '600' }}>Warranty Expiry: {machine.warrantyExpiry || '2026-01-15'}</div>
            </div>
          </div>
        )}

        {/* Tab 2: Live Telemetry */}
        {activeTab === 'telemetry' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1.25rem' }}>
            <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--accent-primary)' }}>
                <Gauge size={20} /> <span style={{ fontWeight: '800', fontSize: '0.85rem' }}>MAIN SHAFT RPM</span>
              </div>
              <div style={{ fontSize: '1.8rem', fontWeight: '800', color: 'var(--text-primary)', margin: '0.4rem 0' }}>{telemetry.rpm} <span style={{ fontSize: '0.9rem', fontWeight: '600' }}>RPM</span></div>
              <div style={{ fontSize: '0.78rem', color: 'var(--status-running)', fontWeight: '700' }}>Normal Operational Speed</div>
            </div>

            <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--status-maintenance)' }}>
                <Thermometer size={20} /> <span style={{ fontWeight: '800', fontSize: '0.85rem' }}>MOTOR TEMP</span>
              </div>
              <div style={{ fontSize: '1.8rem', fontWeight: '800', color: 'var(--text-primary)', margin: '0.4rem 0' }}>{telemetry.temperature}°C</div>
              <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '700' }}>Threshold: 85.0°C</div>
            </div>

            <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--status-idle)' }}>
                <Activity size={20} /> <span style={{ fontWeight: '800', fontSize: '0.85rem' }}>VIBRATION</span>
              </div>
              <div style={{ fontSize: '1.8rem', fontWeight: '800', color: 'var(--text-primary)', margin: '0.4rem 0' }}>{telemetry.vibration} <span style={{ fontSize: '0.9rem', fontWeight: '600' }}>mm/s</span></div>
              <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '700' }}>ISO 10816 Standard</div>
            </div>

            <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--accent-primary)' }}>
                <Zap size={20} /> <span style={{ fontWeight: '800', fontSize: '0.85rem' }}>POWER CONSUMPTION</span>
              </div>
              <div style={{ fontSize: '1.8rem', fontWeight: '800', color: 'var(--text-primary)', margin: '0.4rem 0' }}>{telemetry.energyUsage} <span style={{ fontSize: '0.9rem', fontWeight: '600' }}>kW</span></div>
              <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '700' }}>Total: {telemetry.runningHours} Run Hours</div>
            </div>
          </div>
        )}

        {/* Tab 3: Machine Health & RUL */}
        {activeTab === 'health' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div style={{ padding: '1.5rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
                <h4 style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)' }}>Digital Twin Health Rating</h4>
                <span style={{ fontSize: '1.8rem', fontWeight: '800', color: health.healthScore > 90 ? 'var(--status-running)' : 'var(--status-maintenance)' }}>
                  {health.healthScore} / 100
                </span>
              </div>

              <div style={{ width: '100%', height: '10px', borderRadius: '5px', background: 'var(--border-subtle)', overflow: 'hidden' }}>
                <div
                  style={{
                    width: `${health.healthScore}%`,
                    height: '100%',
                    background: health.healthScore > 90 ? 'var(--status-running)' : 'var(--status-maintenance)',
                  }}
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem', marginTop: '1.25rem' }}>
                <div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>REMAINING USEFUL LIFE (RUL)</div>
                  <div style={{ fontSize: '1.3rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '2px' }}>{health.remainingUsefulLifeDays} Days</div>
                </div>
                <div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>AI PREDICTIVE DIAGNOSTIC</div>
                  <div style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--accent-primary)', marginTop: '2px' }}>{health.aiPrediction}</div>
                </div>
                <div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>FAILURE PROBABILITY</div>
                  <div style={{ fontSize: '1.3rem', fontWeight: '800', color: health.failureProbabilityPct > 15 ? 'var(--status-maintenance)' : 'var(--status-running)', marginTop: '2px' }}>{health.failureProbabilityPct}%</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tab 4: Current Problems & Problem Reason Recorder */}
        {activeTab === 'problems' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h4 style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)' }}>
                Recorded Machine Problems & Reasons ({problems.length})
              </h4>
              <button
                className="btn btn-primary btn-sm"
                onClick={() => setShowProblemForm(!showProblemForm)}
              >
                <PlusCircle size={16} /> {showProblemForm ? 'Cancel Logging' : 'Log New Problem Reason'}
              </button>
            </div>

            {/* Problem Reason Recording Form */}
            {showProblemForm && (
              <form
                onSubmit={handleRecordProblemSubmit}
                style={{
                  padding: '1.25rem',
                  background: 'var(--bg-primary)',
                  borderRadius: 'var(--radius-md)',
                  border: '1px solid var(--accent-primary)',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '1rem',
                }}
              >
                <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--accent-primary)' }}>
                  📝 Record Anomaly / Problem Reason for {machine.assetName}
                </div>

                <div className="form-grid">
                  <div className="form-group">
                    <label>Problem Title / Description <span className="required">*</span></label>
                    <input
                      type="text"
                      className="form-control"
                      placeholder="e.g. Motor Drive Overheating Anomaly"
                      value={problemName}
                      onChange={(e) => setProblemName(e.target.value)}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Severity Level</label>
                    <select
                      className="form-control"
                      value={severity}
                      onChange={(e) => setSeverity(e.target.value)}
                    >
                      <option value="High">High</option>
                      <option value="Critical">Critical</option>
                      <option value="Medium">Medium</option>
                      <option value="Low">Low</option>
                    </select>
                  </div>
                </div>

                <div className="form-group">
                  <label>Reason for Problem / Root Cause Analysis <span className="required">*</span></label>
                  <textarea
                    className="form-control"
                    rows="3"
                    placeholder="e.g. Excessive friction in main bearing housing due to lube contamination"
                    value={rootCause}
                    onChange={(e) => setRootCause(e.target.value)}
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Triggered Sensor / Source</label>
                  <select
                    className="form-control"
                    value={sensorTriggered}
                    onChange={(e) => setSensorTriggered(e.target.value)}
                  >
                    <option value="Motor Temp Sensor TS-01">Motor Temp Sensor TS-01</option>
                    <option value="Vibration Sensor VIB-04">Vibration Sensor VIB-04</option>
                    <option value="Warp Tension Sensor TS-02">Warp Tension Sensor TS-02</option>
                    <option value="Manual Maintenance Inspection">Manual Maintenance Inspection</option>
                  </select>
                </div>

                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem' }}>
                  <button
                    type="button"
                    className="btn btn-secondary btn-sm"
                    onClick={() => setShowProblemForm(false)}
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="btn btn-primary btn-sm"
                    disabled={submitting}
                  >
                    <Save size={16} /> {submitting ? 'Saving Reason...' : 'Record Problem Reason'}
                  </button>
                </div>
              </form>
            )}

            {/* Problems List */}
            {problems.length === 0 ? (
              <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--status-running)', fontWeight: '800', background: 'var(--status-running-bg)', borderRadius: 'var(--radius-sm)' }}>
                <CheckCircle2 size={32} style={{ margin: '0 auto 0.5rem auto' }} />
                No Active Anomalies or Problems Recorded for this Asset.
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                {problems.map((p) => (
                  <div key={p.id} style={{ padding: '1.25rem', background: 'var(--status-maintenance-bg)', borderRadius: 'var(--radius-sm)', border: '1px solid rgba(225, 29, 72, 0.3)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <span style={{ fontWeight: '800', color: 'var(--status-maintenance)', fontSize: '1.05rem' }}>{p.name}</span>
                      <span className="badge badge-maintenance">{p.severity} Priority</span>
                    </div>
                    <div style={{ marginTop: '0.5rem', fontSize: '0.92rem', color: '#0F172A', fontWeight: '800' }}>
                      Reason for Problem: <span style={{ color: 'var(--status-maintenance)' }}>{p.rootCause}</span>
                    </div>
                    <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginTop: '6px', fontWeight: '700' }}>
                      Detected: {p.detectionTime} • Triggered by: {p.sensorTriggered}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Tab 5: Maintenance Records */}
        {activeTab === 'maintenance' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div style={{ padding: '1.25rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ fontSize: '0.85rem', fontWeight: '800', color: 'var(--accent-primary)', marginBottom: '0.5rem' }}>CURRENT MAINTENANCE SESSION</div>
              <div style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--text-primary)' }}>{maint.maintenanceType}</div>
              <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '4px', fontWeight: '600' }}>Issue: {maint.issueDescription}</div>
              <div style={{ fontSize: '0.85rem', color: '#0F172A', marginTop: '4px', fontWeight: '800' }}>Reason / Root Cause: {maint.rootCause}</div>
              <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', marginTop: '4px', fontWeight: '600' }}>Engineer: {maint.engineer} • Priority: {maint.priority}</div>
            </div>

            <h4 style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '0.5rem' }}>Historical Service Log</h4>
            {maint.history.length === 0 ? (
              <div style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', fontWeight: '600' }}>No previous maintenance records logged.</div>
            ) : (
              <div className="table-responsive">
                <table className="custom-table">
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Work Performed</th>
                      <th>Engineer</th>
                      <th>Cost</th>
                      <th>Downtime</th>
                    </tr>
                  </thead>
                  <tbody>
                    {maint.history.map((h, i) => (
                      <tr key={i}>
                        <td style={{ fontWeight: '700', color: 'var(--accent-primary)' }}>{h.date}</td>
                        <td style={{ color: 'var(--text-primary)' }}>{h.workPerformed}</td>
                        <td>{h.engineer}</td>
                        <td style={{ fontWeight: '700' }}>{h.cost}</td>
                        <td style={{ color: 'var(--status-maintenance)' }}>{h.downtime}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {/* Tab 6: Event Timeline */}
        {activeTab === 'timeline' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', paddingLeft: '1rem', borderLeft: '2px solid var(--accent-primary)' }}>
            {timeline.map((item, idx) => (
              <div key={idx} style={{ position: 'relative', paddingLeft: '1rem' }}>
                <div
                  style={{
                    position: 'absolute',
                    left: '-1.45rem',
                    top: '2px',
                    width: '12px',
                    height: '12px',
                    borderRadius: '50%',
                    background: 'var(--accent-primary)',
                  }}
                />
                <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '700' }}>{item.date}</div>
                <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '2px' }}>{item.event}</div>
              </div>
            ))}
          </div>
        )}

        {/* Tab 7: AI Recommendations */}
        {activeTab === 'ai' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div style={{ padding: '1.5rem', background: 'var(--status-critical-bg)', borderRadius: 'var(--radius-md)', border: '1px solid rgba(124, 58, 237, 0.3)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--status-critical)', fontWeight: '800', fontSize: '1.1rem', marginBottom: '0.75rem' }}>
                <Sparkles size={22} /> TexTwin AI Agent Prescriptions
              </div>

              <div style={{ marginBottom: '1rem' }}>
                <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', fontWeight: '800' }}>IMMEDIATE ACTION REQUIRED</div>
                <div style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '2px' }}>{aiRecs.immediateAction}</div>
              </div>

              <div style={{ marginBottom: '1rem' }}>
                <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', fontWeight: '800' }}>PREVENTIVE RECOMMENDATION</div>
                <div style={{ fontSize: '0.95rem', fontWeight: '700', color: 'var(--text-primary)', marginTop: '2px' }}>{aiRecs.preventiveAction}</div>
              </div>

              <div style={{ display: 'flex', gap: '2rem', marginTop: '1.25rem', paddingTop: '1rem', borderTop: '1px solid rgba(124, 58, 237, 0.2)' }}>
                <div>
                  <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '800' }}>ESTIMATED RISK</div>
                  <div style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--status-critical)' }}>{aiRecs.estimatedRisk}</div>
                </div>
                <div>
                  <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '800' }}>NEXT INSPECTION</div>
                  <div style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)' }}>{aiRecs.recommendedInspectionDate}</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Footer Close */}
        <div style={{ marginTop: '2rem', display: 'flex', justifyContent: 'flex-end' }}>
          <button className="btn btn-secondary" onClick={onClose}>
            Close Inspection View
          </button>
        </div>
      </div>
    </div>
  );
};

export default MachineDetailsModal;
